			if (empty($size) || round($size) < 12) {
				$morecss = 'minwidth100';
			} elseif (round($size) <= 48) {
				$morecss = 'minwidth200';
			} else {
				$morecss = 'minwidth400';
			}
		}
	}

	if (in_array($type, array('date'))) {
		$tmp = explode(',', $size);
		$newsize = $tmp[0];
		$showtime = 0;

		// Do not show current date when field not required (see selectDate() method)
